package cl.duoc.biblioteca.view;
import cl.duoc.biblioteca.dao.BibliotecaDAO;
import cl.duoc.biblioteca.model.Usuario;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;
import java.util.*;
import java.util.List;

public class BibliotecaFrame extends JFrame {
 private final Usuario usuario; private final BibliotecaDAO dao=new BibliotecaDAO(); private final JTabbedPane tabs=new JTabbedPane();
 private JTable libros,estudiantes,prestamos,reportes; private DefaultTableModel lm,em,pm,rm;
 public BibliotecaFrame(Usuario u){super("Biblioteca Escolar — "+u.getNombre()+" ("+u.getRol()+")");usuario=u;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,650);setLocationRelativeTo(null);setLayout(new BorderLayout());add(tabs,BorderLayout.CENTER);buildBooks();buildStudents();buildLoans();buildReports();JLabel footer=new JLabel("  Sesión: "+u.getCorreo()+" | Sistema de Gestión de Biblioteca Escolar");add(footer,BorderLayout.SOUTH);reloadAll();}
 private DefaultTableModel model(String... cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
 private JTable table(DefaultTableModel m){JTable t=new JTable(m);t.setAutoCreateRowSorter(true);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);return t;}
 private JPanel panel(JTable t,JButton... buttons){JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));p.add(new JScrollPane(t),BorderLayout.CENTER);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));for(JButton x:buttons)b.add(x);p.add(b,BorderLayout.SOUTH);return p;}
 private JButton button(String s,java.awt.event.ActionListener a){JButton b=new JButton(s);b.addActionListener(a);return b;}
 private void buildBooks(){lm=model("ID","Título","Autor","ISBN","Editorial","Stock","Categoría");libros=table(lm);if(usuario.esBibliotecario())tabs.addTab("Libros",panel(libros,button("Agregar",e->editBook(null)),button("Editar seleccionado",e->editBook(selectedId(libros))),button("Eliminar seleccionado",e->deleteBook())));else tabs.addTab("Consultar libros",new JScrollPane(libros));}
 private void buildStudents(){em=model("ID","Nombre","RUT","Curso","Correo");estudiantes=table(em);if(usuario.esBibliotecario())tabs.addTab("Estudiantes",panel(estudiantes,button("Agregar",e->editStudent(null)),button("Editar seleccionado",e->editStudent(selectedId(estudiantes))),button("Eliminar seleccionado",e->deleteStudent())));}
 private void buildLoans(){pm=model("ID préstamo","Estudiante","Libro","Fecha préstamo","Vencimiento","Devuelto","Estado");prestamos=table(pm);if(usuario.esBibliotecario())tabs.addTab("Préstamos",panel(prestamos,button("Registrar préstamo",e->newLoan()),button("Registrar devolución",e->returnLoan()),button("Actualizar",e->reloadAll())));else tabs.addTab("Préstamos y devoluciones",panel(prestamos,button("Solicitar préstamo",e->newLoan()),button("Devolver seleccionado",e->returnLoan()),button("Actualizar",e->reloadAll())));}
 private void buildReports(){rm=model("Dato 1","Dato 2","Dato 3","Dato 4","Dato 5");reportes=table(rm);JComboBox<String> tipo=new JComboBox<>(new String[]{"Más prestados","Historial por estudiante","Préstamos activos"});JButton ver=button("Generar reporte",e->loadReport((String)tipo.getSelectedItem()));JPanel p=panel(reportes,ver);JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.add(new JLabel("Reporte:"));top.add(tipo);top.add(ver);p.add(top,BorderLayout.NORTH);tabs.addTab("Reportes",p);}
 private Integer selectedId(JTable t){int row=t.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Selecciona una fila primero.");return null;}return Integer.parseInt(t.getValueAt(t.convertRowIndexToModel(row),0).toString());}
 private void reloadAll(){load(lm,()->dao.libros());if(em!=null&&usuario.esBibliotecario())load(em,()->dao.estudiantes());load(pm,()->dao.prestamos());}
 private interface Query {List<Object[]> run() throws Exception;}
 private void load(DefaultTableModel m,Query q){try{m.setRowCount(0);for(Object[] r:q.run())m.addRow(r);}catch(Exception ex){error(ex);}}
 private void loadReport(String tipo){try{rm.setRowCount(0);for(Object[] r:dao.reporte(tipo))rm.addRow(Arrays.copyOf(r,Math.max(5,r.length)));}catch(Exception ex){error(ex);}}
 private void editBook(Integer id){if(id==null&&libros.getSelectedRow()>=0){} JTextField titulo=new JTextField(),autor=new JTextField(),isbn=new JTextField(),editorial=new JTextField(),stock=new JTextField("1");JComboBox<String> cat=new JComboBox<>();try{for(String c:dao.categorias())cat.addItem(c);}catch(Exception ex){error(ex);return;}if(id!=null){int r=libros.convertRowIndexToModel(libros.getSelectedRow());titulo.setText(""+lm.getValueAt(r,1));autor.setText(""+lm.getValueAt(r,2));isbn.setText(""+lm.getValueAt(r,3));editorial.setText(""+lm.getValueAt(r,4));stock.setText(""+lm.getValueAt(r,5));}JPanel p=new JPanel(new GridLayout(0,2,5,5));for(Object[] pair:new Object[][]{{"Título",titulo},{"Autor",autor},{"ISBN",isbn},{"Editorial",editorial},{"Stock",stock},{"Categoría",cat}}){p.add(new JLabel(pair[0].toString()));p.add((Component)pair[1]);}if(JOptionPane.showConfirmDialog(this,p,id==null?"Nuevo libro":"Editar libro",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){try{int st=Integer.parseInt(stock.getText().trim());int categoria=Integer.parseInt(cat.getSelectedItem().toString().split(" - ")[0]);dao.guardarLibro(id,titulo.getText().trim(),autor.getText().trim(),isbn.getText().trim(),editorial.getText().trim(),st,categoria);reloadAll();}catch(Exception ex){error(ex);}}}
 private void deleteBook(){Integer id=selectedId(libros);if(id!=null&&JOptionPane.showConfirmDialog(this,"¿Eliminar el libro seleccionado?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{dao.eliminarLibro(id);reloadAll();}catch(Exception ex){error(ex);}}
 private void editStudent(Integer id){JTextField nombre=new JTextField(),rut=new JTextField(),curso=new JTextField(),correo=new JTextField();if(id!=null){int r=estudiantes.convertRowIndexToModel(estudiantes.getSelectedRow());nombre.setText(""+em.getValueAt(r,1));rut.setText(""+em.getValueAt(r,2));curso.setText(""+em.getValueAt(r,3));correo.setText(""+em.getValueAt(r,4));}JPanel p=new JPanel(new GridLayout(0,2,5,5));for(Object[] pair:new Object[][]{{"Nombre",nombre},{"RUT",rut},{"Curso",curso},{"Correo",correo}}){p.add(new JLabel(pair[0].toString()));p.add((Component)pair[1]);}if(JOptionPane.showConfirmDialog(this,p,id==null?"Nuevo estudiante":"Editar estudiante",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{dao.guardarEstudiante(id,nombre.getText().trim(),rut.getText().trim(),curso.getText().trim(),correo.getText().trim());reloadAll();}catch(Exception ex){error(ex);}}
 private void deleteStudent(){Integer id=selectedId(estudiantes);if(id!=null&&JOptionPane.showConfirmDialog(this,"¿Eliminar el estudiante seleccionado?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{dao.eliminarEstudiante(id);reloadAll();}catch(Exception ex){error(ex);}}
 private void newLoan(){try{List<Object[]> es=dao.estudiantes(),ls=dao.libros();if(es.isEmpty()||ls.isEmpty())throw new SQLException("Debe haber estudiantes y libros registrados.");String[] optsE=es.stream().map(r->r[0]+" - "+r[1]).toArray(String[]::new);String[] optsL=ls.stream().map(r->r[0]+" - "+r[1]+" (stock: "+r[5]+")").toArray(String[]::new);JComboBox<String> ce=new JComboBox<>(optsE),cl=new JComboBox<>(optsL);JPanel p=new JPanel(new GridLayout(0,2,5,5));p.add(new JLabel("Estudiante"));p.add(ce);p.add(new JLabel("Libro"));p.add(cl);if(JOptionPane.showConfirmDialog(this,p,"Registrar préstamo (7 días)",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;int estudiante=Integer.parseInt(ce.getSelectedItem().toString().split(" - ")[0]),libro=Integer.parseInt(cl.getSelectedItem().toString().split(" - ")[0]);JOptionPane pane=new JOptionPane("Procesando préstamo en segundo plano…",JOptionPane.INFORMATION_MESSAGE);JDialog wait=pane.createDialog(this,"Préstamo");SwingWorker<Void,Void> worker=new SwingWorker<>(){protected Void doInBackground()throws Exception{dao.prestar(estudiante,libro);return null;}protected void done(){wait.dispose();try{get();JOptionPane.showMessageDialog(BibliotecaFrame.this,"Préstamo registrado. Vencimiento: en 7 días.");reloadAll();}catch(Exception ex){error(ex.getCause()==null?ex:ex.getCause());}}};worker.execute();wait.setModal(false);wait.setVisible(true);}catch(Exception ex){error(ex);}}
 private void returnLoan(){Integer id=selectedId(prestamos);if(id==null)return;try{dao.devolver(id);JOptionPane.showMessageDialog(this,"Devolución registrada y stock actualizado.");reloadAll();}catch(Exception ex){error(ex);}}
 private void error(Throwable ex){JOptionPane.showMessageDialog(this,ex.getMessage()==null?ex.toString():ex.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}
}
